        if 'Before' in directives:
            for before in directives['Before']:
                graph[canonical_target].add(before)
        # After = Z1 Z2 ... → Z1 → canonical_target
        if 'After' in directives:
            for after in directives['After']:
                graph[after].add(canonical_target)
        # Needs = W1 W2 ... → canonical_target → W1
        if 'Needs' in directives:
            for needs in directives['Needs']:
                graph[canonical_target].add(needs)
        # Requires = V1 V2 ... → canonical_target → V1
        if 'Requires' in directives:
            for req in directives['Requires']:
                graph[canonical_target].add(req)

